let importBook=[],importFile='',importPreview=[],reviewSelection=null;
function showTab(id){if(id==='entries')id='import';document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===id));for(const k of ['import','salary','staff','rules','report'])$(k).classList.toggle('hidden',k!==id)}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>showTab(b.dataset.tab));
$('jumpManual').onclick=()=>{$('entries').scrollIntoView({behavior:'smooth',block:'start'});$('teacher').focus({preventScroll:true})};
function invalidatePreview(){importPreview=[];$('commitImport').disabled=true;$('previewBody').innerHTML='';$('importStats').textContent='设置已变化，请重新预览匹配结果。'}
function sheetConfig(i){const box=$('sheet-'+i),sheet=importBook[i],head=Number(box.querySelector('[data-header]').value)-1,map={};box.querySelectorAll('[data-map]').forEach(s=>map[s.dataset.map]=Number(s.value));return {sheet,head,map,source:box.querySelector('[data-source]').value,selected:box.querySelector('[data-enabled]').checked}}
function mappingHTML(sheet,head,map){const cells=sheet.rows[head]?.cells||[];return Object.entries(PayrollMatch.labels).map(([k,label])=>`<label>${esc(label)}<select data-map="${k}"><option value="-1">未对应</option>${Array.from({length:cells.length},(_,c)=>`<option value="${c}" ${map[k]===c?'selected':''}>${ExcelIO.col(c)} · ${esc(cells[c]||'空白列')}</option>`).join('')}</select></label>`).join('')}
function drawSheets(){const candidates=importBook.map(s=>PayrollMatch.header(s.rows));$('sheetConfigs').innerHTML=importBook.map((s,i)=>{const h=candidates[i],employee=(h.map.version>=0||h.map.newVersion>=0)&&h.map.student<0,source=employee?'staff':((h.map.fullPaid>=0&&h.map.package>=0)||(h.map.trialDate>=0&&h.map.enrolledCourse>=0))?'signup':h.map.project>=0&&s.rows[h.at]?.cells.some(c=>PayrollMatch.norm(c)==='审核类型')?'project':'settlement';const selected=!s.hidden&&h.map.teacher>=0&&(employee||h.map.student>=0)&&(source==='signup'||!(/课时统计|试听|国际学校/.test(s.name)));return `<article class="sheetconfig" id="sheet-${i}"><div class="actions" style="margin:0"><label class="check"><input type="checkbox" data-enabled ${selected?'checked':''}>${esc(s.name)}${s.hidden?'（隐藏工作表）':''}</label><span class="muted">${s.rows.length} 行</span><label>表头行<select data-header>${s.rows.slice(0,60).map((r,at)=>`<option value="${at+1}" ${at===h.at?'selected':''}>第${r.number}行 · ${esc(r.cells.filter(Boolean).slice(0,3).join(' / ').slice(0,55))}</option>`).join('')}</select></label><label>数据用途<select data-source><option value="project" ${source==='project'?'selected':''}>项目审核表</option><option value="settlement" ${source==='settlement'?'selected':''}>结算类统计表</option><option value="staff" ${source==='staff'?'selected':''}>员工版本名单</option><option value="signup" ${source==='signup'?'selected':''}>教师辅助签约奖励表</option></select></label></div><details><summary>查看 / 调整列名对应</summary><div class="form mapgrid">${mappingHTML(s,h.at,h.map)}</div></details></article>`}).join('');$('importSettings').classList.remove('hidden');invalidatePreview()}
$('importFile').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;$('importStats').textContent='正在读取表格…';importBook=await ExcelIO.read(file);importFile=file.name;drawSheets();$('fileName').textContent=importFile;toast('文件已读取，请预览匹配结果')}catch(err){$('importStats').textContent=err.message;toast(err.message)}};
$('sheetConfigs').onchange=e=>{if(e.target.hasAttribute('data-header')){const box=e.target.closest('.sheetconfig'),i=Number(box.id.split('-')[1]),head=Number(e.target.value)-1;box.querySelector('.mapgrid').innerHTML=mappingHTML(importBook[i],head,PayrollMatch.mapping(importBook[i].rows[head]?.cells||[]))}invalidatePreview()};
$('onlyVisible').onchange=invalidatePreview;$('month').addEventListener('change',invalidatePreview);
function semanticKey(e){const r=ruleBy(e.rule);if(!r||r.unit==='小时'||!e.project)return '';return [e.teacher,e.student,e.project,e.version,r.group,r.item].join('|')}
function fingerprint(s){let hash=2166136261;for(let i=0;i<s.length;i++){hash^=s.charCodeAt(i);hash=Math.imul(hash,16777619)}return (hash>>>0).toString(16)}
function buildPreview(){try{importPreview=[];const configs=importBook.map((_,i)=>sheetConfig(i)).filter(c=>c.selected);if(!configs.length)throw Error('请至少选择一张工作表');let staff={...state.staff},staffPolicies={...(state.staffRules||{})},staffChanges=[],skippedHidden=0,empty=0;
 for(const c of configs){if(c.map.teacher<0)throw Error(c.sheet.name+'：请对应负责老师列');if(c.source==='staff'&&c.map.version<0&&c.map.newVersion<0)throw Error(c.sheet.name+'：请对应绩效版本列');if(c.source!=='staff'&&(c.map.student<0||(c.map.type<0&&c.source!=='signup')))throw Error(c.sheet.name+'：请对应学生姓名和审核 / 结算类型列');if(c.source==='staff')for(const row of c.sheet.rows.slice(c.head+1)){if($('onlyVisible').checked&&row.hidden)continue;let d=PayrollMatch.record(row.cells,c.map);if(!d.teacher)continue;const v=PayrollMatch.version(d.newVersion||d.version);if(!v)throw Error(c.sheet.name+'第'+row.number+'行：无法识别版本 '+d.version);if(staffChanges.some(x=>x.teacher===d.teacher&&x.version!==v))throw Error('员工名单中同一老师有冲突版本：'+d.teacher);let policy=null;if([d.oldVersion,d.oldBefore,d.newVersion,d.newFrom].some(Boolean)){policy={oldVersion:PayrollMatch.version(d.oldVersion),oldBefore:StaffVersionPolicy.date(d.oldBefore),newVersion:PayrollMatch.version(d.newVersion),newFrom:StaffVersionPolicy.date(d.newFrom)};const error=StaffVersionPolicy.validate(policy);if(error)throw Error(d.teacher+'：'+error);staffPolicies[d.teacher]=policy}const prior=staffChanges.find(x=>x.teacher===d.teacher);if(prior&&JSON.stringify(prior.policy||null)!==JSON.stringify(policy))throw Error(d.teacher+'的签约日期规则重复且冲突');staff[d.teacher]=v;staffChanges.push({teacher:d.teacher,version:v,policy})}}
 const seenSource=new Set(state.entries.map(e=>e.sourceKey).filter(Boolean)),seenSemantic=new Set(state.entries.filter(e=>!e.excludedReason).map(semanticKey).filter(Boolean)),month=$('month').value;
 for(const c of configs){if(c.source==='staff')continue;for(const row of c.sheet.rows.slice(c.head+1)){if($('onlyVisible').checked&&row.hidden){skippedHidden++;continue}const d=PayrollMatch.record(row.cells,c.map);if(c.source==='signup'&&!d.type)d.type='辅助签约';if(!Object.values(d).some(Boolean)){empty++;continue}if(PayrollMatch.norm(d.teacher)===PayrollMatch.norm(c.sheet.rows[c.head].cells[c.map.teacher])&&PayrollMatch.norm(d.student)===PayrollMatch.norm(c.sheet.rows[c.head].cells[c.map.student]))continue;
  for(const part of (c.source==='signup'?PayrollMatch.expandSignup(d):[d])){const e={...PayrollMatch.match(part,c.source,staff,staffPolicies),id:crypto.randomUUID(),month,sourceKind:c.source,sourceFile:importFile,sourceSheet:c.sheet.name,sourceRow:row.number,manualResolved:false};e.sourceKey=JSON.stringify([c.sheet.name,row.number,row.cells,...(part.signupShareCount>1?[part.teacher,part.signupTeacherIndex]:[])]);e.sourceLabel=importFile+' / '+c.sheet.name+' / 第'+row.number+'行';
  if(seenSource.has(e.sourceKey)){e.duplicate=true;e.excludedReason='重复记录（已存在或本次重复）'}else{seenSource.add(e.sourceKey)}importPreview.push(e)}
 }}
 importPreview.staffChanges=staffChanges;importPreview.hiddenCount=skippedHidden;drawPreview();$('commitImport').disabled=!importPreview.some(e=>!e.duplicate)&&!staffChanges.length;
 }catch(err){invalidatePreview();$('importStats').textContent=err.message;toast(err.message)}}
function drawPreview(){const counts={ok:0,pending:0,excluded:0,duplicate:0},total=importPreview.reduce((sum,e)=>{let c=calculate(e);if(e.duplicate)counts.duplicate++;else if(c.status==='可结算')counts.ok++;else if(c.status.startsWith('排除'))counts.excluded++;else counts.pending++;return sum+c.amount},0);$('importStats').textContent=`${importPreview.length} 条记录：可结算 ${counts.ok} · 待确认 ${counts.pending} · 排除 ${counts.excluded} · 重复跳过 ${counts.duplicate} ｜ 绩效 ¥${money(total)} ｜ 跳过隐藏行 ${importPreview.hiddenCount||0} ｜ 员工版本 ${importPreview.staffChanges?.length||0} 人。`;
 $('previewBody').innerHTML=importPreview.slice(0,300).map(e=>{const r=ruleBy(e.rule),c=calculate(e);return `<tr><td>${esc(e.sourceSheet)}<br><small>第${e.sourceRow}行</small></td><td>${esc(e.teacher)}<br><small>${esc(e.version)}${e.versionDefault?'（默认）':''}</small></td><td>${esc(e.student)}</td><td class="wrap">${esc(e.raw.type+' '+e.raw.project)}</td><td class="wrap">${r?esc(r.group+' / '+r.item+' / '+r.tier):'—'}</td><td>${e.qty} × ${e.ratio}</td><td>${c.status==='可结算'?'¥'+money(c.amount):'—'}</td><td class="wrap"><span class="pill ${performanceStatusClass(c.status)}">${esc(c.status)}</span></td><td><button data-preview-edit="${e.id}" ${e.duplicate?"disabled":""}>修正 / 匹配</button> <button class="danger" data-performance-delete="${e.id}" data-delete-kind="preview">删除</button></td></tr>`}).join('');$('previewLimit').textContent=importPreview.length>300?'预览仅显示前300条，确认后会导入全部记录。':''}
$('previewImport').onclick=buildPreview;
$('commitImport').onclick=()=>{if(!importPreview.length&&!importPreview.staffChanges?.length)return;if(!$('confirmDefault').checked&&importPreview.some(e=>e.versionDefault&&!e.excludedReason))return toast('请确认未指定版本的老师先按常规版计算，或先导入员工版本名单');let entries=importPreview.filter(e=>!e.duplicate),before=state.entries.length,beforeStaff={...state.staff},beforeRules={...(state.staffRules||{})};state.entries.push(...entries);for(const s of importPreview.staffChanges||[]){state.staff[s.teacher]=s.version;if(s.policy){state.staffRules||={};state.staffRules[s.teacher]=s.policy}}try{save()}catch{state.entries.splice(before);state.staff=beforeStaff;state.staffRules=beforeRules;return toast('浏览器存储空间不足，请先导出备份并分批导入')}importPreview=[];$('commitImport').disabled=true;render();renderReview();showTab('import');$('importStats').textContent='导入完成：'+entries.length+'条。下方可集中处理待确认记录；可结算金额已同步到工资汇总。';$('previewBody').innerHTML='';toast('导入完成，工资已汇总')};
function reviewPerformanceType(e){const r=ruleBy(e.rule);return e.sourceKind==='signup'||/辅助签约/.test(e.raw?.type||'')||/签约/.test((r?.group||'')+' '+(r?.item||''))?'signup':'fee'}
function reviewVisibleEntries(){const q=$('reviewFilter').value,type=$('reviewTypeFilter').value;return monthEntries().filter(e=>(type==='all'||reviewPerformanceType(e)===type)&&(q==='pending'?calculate(e).status.startsWith('待'):q==='excluded'?calculate(e).status.startsWith('排除'):q==='confirmed'?calculate(e).status==='可结算':true))}
function renderReview(){let all=monthEntries(),rows=reviewVisibleEntries();$('reviewCount').textContent=all.filter(e=>calculate(e).status.startsWith('待')).length+' 条待确认';const teacherSort=new Intl.Collator('zh-Hans-CN-u-co-pinyin',{usage:'sort',sensitivity:'base',numeric:true});rows.sort((a,b)=>{const name=e=>String(e.teacher||'').trim(),missing=e=>!name(e)||/^[/／—-]+$/.test(name(e));return Number(missing(a))-Number(missing(b))||teacherSort.compare(name(a),name(b))});$('reviewBody').innerHTML=rows.map(e=>{let r=ruleBy(e.rule),c=calculate(e);return `<tr><td><input type="checkbox" data-review-select="${esc(e.id)}" aria-label="选择${esc(e.teacher)}的记录"></td><td>${reviewPerformanceType(e)==='signup'?'签约辅助':'课酬'}</td><td>${esc(e.teacher)}<br><small>${esc(e.version)}</small></td><td>${esc(e.student)}</td><td class="wrap">${esc(e.raw?.type||r?.item||'未匹配')} ${esc(e.raw?.project||e.project)}<br><small>${esc(e.sourceLabel||'手动录入')}</small></td><td class="wrap">${esc(r?r.group+' / '+r.item+' / '+r.tier:'未匹配')}</td><td>${c.status==='可结算'?'¥'+money(c.amount):'—'}</td><td class="wrap"><span class="pill ${performanceStatusClass(c.status)}">${esc(c.status)}</span></td><td><button data-review="${e.id}">核对 / 修改</button> <button class="danger" data-performance-delete="${e.id}" data-delete-kind="saved">删除</button></td></tr>`}).join('')||'<tr><td colspan="9">当前没有此类记录。</td></tr>'}
$('reviewFilter').onchange=renderReview;$('month').addEventListener('change',renderReview);
function reviewOptions(v){$('reviewRule').innerHTML='<option value="">请选择计费规则</option>'+RULES.filter(r=>r.version===v).map(r=>`<option value="${r.id}">${esc(r.group+' · '+r.item+' · '+r.tier+' ｜ '+r.rate+'元/'+r.unit)}</option>`).join('')}
$('reviewBody').onclick=e=>{let id=e.target.dataset.review;if(!id)return;let entry=state.entries.find(e=>e.id===id);reviewSelection=id;$('reviewPanel').classList.remove('hidden');$('reviewHeading').textContent=entry.teacher+' / '+entry.student;$('reviewOriginal').textContent=entry.sourceLabel+' ｜ '+Object.entries(entry.raw||{}).filter(([,v])=>v).map(([k,v])=>(PayrollMatch.labels[k]||k)+': '+v).join(' ｜ ');$('reviewVersion').value=entry.version;reviewOptions(entry.version);$('reviewRule').value=entry.rule;for(const [id,k]of [['reviewQty','qty'],['reviewRatio','ratio'],['reviewProject','project'],['reviewNature','nature'],['reviewOverride','override'],['reviewReason','reason']])$(id).value=entry[k]??'';$('reviewExclude').checked=!!entry.excludedReason;$('reviewPanel').scrollIntoView({behavior:'smooth',block:'center'})};
$('reviewVersion').onchange=()=>reviewOptions($('reviewVersion').value);$('reviewCancel').onclick=()=>$('reviewPanel').classList.add('hidden');
$('reviewForm').onsubmit=e=>{e.preventDefault();const old=state.entries.find(e=>e.id===reviewSelection);if(!old)return;const excluded=$('reviewExclude').checked;if(!excluded&&!$('reviewRule').value)return toast('请选择计费规则');const override=$('reviewOverride').value===''?null:Number($('reviewOverride').value),reason=$('reviewReason').value.trim();if(override!==null&&!reason)return toast('人工调整金额时请填写原因');let updated={...old,version:$('reviewVersion').value,rule:$('reviewRule').value,qty:Number($('reviewQty').value),ratio:Number($('reviewRatio').value),project:$('reviewProject').value,nature:$('reviewNature').value,override,reason,manualResolved:true,importIssue:'',excludedReason:excluded?'人工排除':'',condition:'yes'};state.entries=state.entries.map(x=>x.id===old.id?updated:x);render();renderReview();$('reviewPanel').classList.add('hidden');toast('已更新绩效与工资汇总')};
$('rematch').onclick=()=>{let n=0;state.entries=state.entries.map(e=>{if(e.month!==$('month').value||!e.raw||e.manualResolved||e.duplicate)return e;n++;let next={...e,...PayrollMatch.match(e.raw,e.sourceKind,state.staff,state.staffRules||{})};if(e.importIssue?.includes('重复'))next.importIssue=e.importIssue;return next});render();renderReview();toast('已重新匹配'+n+'条未人工修改的记录')};
async function exportWorkbook(){try{const all=monthEntries(),pending=all.filter(e=>calculate(e).status.startsWith('待'));if(pending.length&&!confirm('仍有'+pending.length+'条待确认，工资汇总不含这些金额，文件会附上待确认明细。继续？'))return;const head=['月份','负责老师','性质','版本','学生','产品类别','绩效项目','套餐档位','项目编号','数量/小时','单价','结算比例','绩效金额','状态','原始内容','来源文件','工作表','原始行号','备注','调整原因'];const detail=e=>{let r=ruleBy(e.rule)||{},c=calculate(e);return [e.month,e.teacher,e.nature,e.version,e.student,r.group,r.item,r.tier,e.project,e.qty,c.rate??r.rate,e.ratio,c.status==='可结算'?c.amount:'',c.status,e.raw?.type||'',e.sourceFile||'',e.sourceSheet||'',e.sourceRow||'',e.note,e.reason]};let rows=[['月份','员工','绩效版本','基本工资','已确认绩效','补贴','其他扣款','应发工资（未扣个税及社保公积金）','待确认记录数'],...salaryData().map(s=>[$('month').value,s.name,s.version,s.base,s.perf,s.allowance,s.deduct,Math.round(s.total*100)/100,pending.filter(e=>e.teacher===s.name).length])];const blob=await ExcelIO.write([{name:'工资汇总',rows},{name:'绩效明细',rows:[head,...all.map(detail)]},{name:'待确认',rows:[head,...pending.map(detail)]}]);download(blob,$('month').value+'工资与绩效.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')}catch(err){toast('导出失败：'+err.message)}}
$('excelExport').onclick=exportWorkbook;$('excelExportTop').onclick=exportWorkbook;
$('sampleCSV').onclick=()=>csv([['负责老师','老师性质','学生姓名','合同国家','学生套餐','申请学历','科系','申请专业','结算类型','项目序号','项目进度','绩效版本'],['演示导师A','全职','演示学生A','英国','Top3','MA','时尚设计科系','服装设计','项目','1',1,'常规版'],['演示导师B','全职','演示学生B','英国','Top5','研究生','','','研究生1V1基础课mini 2.5小时','',1,'24版'],['演示导师C','全职','演示学生C','英国','Top5','研究生','','','项目','2',.5,'22版'],['演示导师D','兼职','演示学生D','英国','Top3','MA','','','排版指导（项目三）','3',1,'常规版']], '批量导入示例.csv');
